#!/usr/bin/env bash

set -euo pipefail

here=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
temp_dir="$(mktemp -d)"
autogenerated="models/autogenerated.py"

cleanup() {
	rm -rf "$temp_dir"
}

trap cleanup EXIT ERR

main() {
	cd "$temp_dir"
	(
		echo '[tool.black]
line-length = 200
'
	) >"$temp_dir/pyproject.toml"
	(
		echo 'from __future__ import annotations

from datetime import date
from enum import Enum
from typing import Any

from pydantic import (
	AwareDatetime,
	ConfigDict,
	Field,
	NaiveDatetime,
	RootModel,
	alias_generators,
	model_validator,
)
from snowfall.stdlib.integration.pydantic import model

AwareOrNaiveDatetime = AwareDatetime | NaiveDatetime


class BaseModel(model.DefaultingBaseModel):
	model_config = ConfigDict(
		alias_generator=alias_generators.to_camel,
		populate_by_name=True,
		from_attributes=True,
	)

		'
		docker run --rm -v "$PWD":/dir koxudaxi/datamodel-code-generator:0.25.5 \
			--url https://api.one.junction.dev/v1/api-docs.json \
			--input-file-type openapi \
			--output-model-type pydantic_v2.BaseModel \
			--output /dir/temp.py \
			--use-union-operator \
			--target-python-version 3.11 \
			--snake-case-field

		grep -v '^#' <temp.py |
			grep -v '^from __future__ import annotations' |
			grep -v '^from datetime import date' |
			grep -v '^from enum import Enum' |
			grep -v '^from pydantic import' |
			sed 's/from datetime import date, datetime/from datetime import date/g' |
			sed -r 's/AwareDatetime/AwareOrNaiveDatetime/g' |
			sed -r 's/constr[^)]+\)/str/g' |
			sed -r 's/(: List\[.+\]) \| None = Field\(None, (.+)\)/\1 = Field(\2, default_factory=list)/g' |
			sed -r 's/(: Dict\[.+\]) \| None = Field\(None, (.+)\)/\1 = Field(\2, default_factory=dict)/g' |
			sed -r 's/(: List\[.+\]) \| None = None/\1 = Field(default_factory=list)/g' |
			sed -r 's/(: Dict\[.+\]) \| None = None/\1 = Field(default_factory=dict)/g'
	) >"$here/$autogenerated"

	cd "$here"
	pants fix fmt lint check "$autogenerated"
}

main
